WITH exploded AS (SELECT id, plan, effective_from, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS tier_value), valid AS (SELECT *, INITCAP(TRIM(plan)) AS plan_title FROM exploded WHERE effective_from BETWEEN '2023-05-01' AND '2025-06-01'), kept_keys AS (SELECT id FROM valid EXCEPT SELECT id FROM price_tiers WHERE effective_from BETWEEN '2024-09-21' AND '2025-04-05'), reconciled AS (SELECT s.* FROM valid s JOIN kept_keys k ON s.id = k.id), valid_price_tiers AS (SELECT plan, LENGTH(plan) AS plan_length FROM reconciled WHERE effective_from >= DATE '2024-03-24'), with_windows AS (SELECT *, MAX(plan_length) OVER w_grp AS plan_max_plan_length, MAX(plan_length) OVER w_grp AS plan_max_plan_length_2, STDDEV_SAMP(plan_length) OVER w_grp AS plan_stddev_samp_plan_length, DENSE_RANK() OVER w_recent AS plan_length_dense_rank, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY plan_length DESC) AS plan_length_percent_rank FROM valid_price_tiers WINDOW w_grp AS (PARTITION BY plan), w_recent AS (PARTITION BY plan ORDER BY plan_length NULLS LAST)) SELECT CASE WHEN plan_max_plan_length >= 67 THEN 'LARGE' ELSE 'SMALL' END AS plan_max_plan_length_tier, COUNT_IF(plan = 'basic') AS basic_events, APPROX_PERCENTILE(plan_length_percent_rank, ARRAY(0.25, 0.5, 0.75)) AS plan_length_percent_rank_quartiles, SUM(CASE WHEN plan = 'pro' THEN plan_length ELSE 0 END) AS pro_plan_length FROM with_windows GROUP BY 1 ORDER BY basic_events DESC NULLS FIRST
